    // Nibble-level bit-reverse lookup: index 0..15 → reversed nibble shifted left by 4
    private static readonly Vector256<byte> NibbleReverseLo = Vector256.Create(
        (byte)0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
