              0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
              0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F);

    private static readonly Vector256<byte> NibbleReverseHi = Vector256.Create(
        (byte)0x00, 0x80, 0x40, 0xC0, 0x20, 0xA0, 0x60, 0xE0,
              0x10, 0x90, 0x50, 0xD0, 0x30, 0xB0, 0x70, 0xF0,
              0x00, 0x80, 0x40, 0xC0, 0x20, 0xA0, 0x60, 0xE0,
              0x10, 0x90, 0x50, 0xD0, 0x30, 0xB0, 0x70, 0xF0);

    private static readonly Vector128<byte> NibbleReverseLo128 = Vector128.Create(
        (byte)0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
              0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F);

    private static readonly Vector128<byte> NibbleReverseHi128 = Vector128.Create(
        (byte)0x00, 0x80, 0x40, 0xC0, 0x20, 0xA0, 0x60, 0xE0,
              0x10, 0x90, 0x50, 0xD0, 0x30, 0xB0, 0x70, 0xF0);

