        ref byte start = ref MemoryMarshal.GetReference(data);
        int length = data.Length;
        int i = 0;

        // AVX2 path: process 32 bytes at a time using VPSHUFB nibble-swap
        if (Avx2.IsSupported)
        {
            Vector256<byte> lowNibbleMask = Vector256.Create((byte)0x0F);

