            {
                Vector256<byte> vec = Vector256.LoadUnsafe(ref start, (nuint)i);
                Vector256<byte> lo = vec & lowNibbleMask;
                Vector256<byte> hi = Vector256.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & lowNibbleMask;
                Vector256<byte> result = Avx2.Shuffle(NibbleReverseHi, lo) | Avx2.Shuffle(NibbleReverseLo, hi);
                result.StoreUnsafe(ref start, (nuint)i);
                i += 32;
            }
        }

        // SSSE3 / AdvSimd path: process 16 bytes at a time
        if (Ssse3.IsSupported)
        {
            Vector128<byte> lowNibbleMask = Vector128.Create((byte)0x0F);

            while (i + 16 <= length)
            {
                Vector128<byte> vec = Vector128.LoadUnsafe(ref start, (nuint)i);
                Vector128<byte> lo = vec & lowNibbleMask;
                Vector128<byte> hi = Vector128.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & lowNibbleMask;
                Vector128<byte> result = Ssse3.Shuffle(NibbleReverseHi128, lo) | Ssse3.Shuffle(NibbleReverseLo128, hi);
                result.StoreUnsafe(ref start, (nuint)i);
                i += 16;
            }
        }
        else if (AdvSimd.IsSupported)
        {
            Vector128<byte> lowNibbleMask = Vector128.Create((byte)0x0F);

            while (i + 16 <= length)
            {
                Vector128<byte> vec = Vector128.LoadUnsafe(ref start, (nuint)i);
                Vector128<byte> lo = vec & lowNibbleMask;
                Vector128<byte> hi = Vector128.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & lowNibbleMask;
                Vector128<byte> result = AdvSimd.Arm64.VectorTableLookup(NibbleReverseHi128, lo)
                                       | AdvSimd.Arm64.VectorTableLookup(NibbleReverseLo128, hi);
                result.StoreUnsafe(ref start, (nuint)i);
                i += 16;
            }
        }

        // Scalar fallback: lookup table for remaining bytes
        ReadOnlySpan<byte> lut = LookupTable;
        ref byte lutRef = ref MemoryMarshal.GetReference(lut);
        for (; i < length; i++)
        {
            Unsafe.Add(ref start, i) = Unsafe.Add(ref lutRef, Unsafe.Add(ref start, i));
        }
    }
}

